8	function assignProps<T extends object>(target: T, ...sources: object[]): T {
9	  for (const source of sources) {
10	    for (const key of Reflect.ownKeys(source)) {
11	      if (Object.prototype.propertyIsEnumerable.call(source, key)) {
12	        assignProp(target, key, (source as any)[key]);
13	      }
14	    }
15	  }
16	  return target;
17	}
