19	export type Processor<T extends schemas.$ZodType = schemas.$ZodType> = (
20	  schema: T,
21	  ctx: ToJSONSchemaContext,
22	  json: JSONSchema.BaseSchema,
23	  params: ProcessParams
24	) => void;
