62	/**
63	 * Parameters for the toJSONSchema function.
64	 */
65	export type ToJSONSchemaParams = Omit<JSONSchemaGeneratorParams, "processors" | "external">;
66	
67	/**
68	 * Parameters for the toJSONSchema function when passing a registry.
69	 */
70	export interface RegistryToJSONSchemaParams extends ToJSONSchemaParams {
71	  uri?: (id: string) => string;
72	}
73	
74	export interface ProcessParams {
75	  schemaPath: schemas.$ZodType[];
76	  path: (string | number)[];
77	}
