79	export interface Seen {
80	  /** JSON Schema result for this Zod schema */
81	  schema: JSONSchema.BaseSchema;
82	  /** A cached version of the schema that doesn't get overwritten during ref resolution */
83	  def?: JSONSchema.BaseSchema;
84	  defId?: string | undefined;
85	  /** Number of times this schema was encountered during traversal */
86	  count: number;
87	  /** Cycle path */
88	  cycle?: (string | number)[] | undefined;
89	  isParent?: boolean | undefined;
90	  /** Deferred `unrepresentable: "throw"` error, thrown after `override` gets a chance to handle it */
91	  unrepresentable?: string | undefined;
92	  /** Schema to inherit JSON Schema properties from (set by processor for wrappers) */
93	  ref?: schemas.$ZodType | null;
