98	export interface ToJSONSchemaContext {
99	  processors: Record<string, Processor>;
100	  metadataRegistry: $ZodRegistry<Record<string, any>>;
101	  target: "draft-04" | "draft-07" | "draft-2020-12" | "openapi-3.0" | ({} & string);
102	  unrepresentable: "throw" | "any";
103	  override: (ctx: {
