132	export function initializeContext(params: JSONSchemaGeneratorParams): ToJSONSchemaContext {
133	  // Normalize target: convert old non-hyphenated versions to hyphenated versions
134	  let target: ToJSONSchemaContext["target"] = params?.target ?? "draft-2020-12";
135	  if (target === "draft-4") target = "draft-04";
136	  if (target === "draft-7") target = "draft-07";
137	
138	  return {
139	    processors: params.processors ?? {},
140	    metadataRegistry: params?.metadata ?? globalRegistry,
141	    target,
142	    unrepresentable: params?.unrepresentable ?? "throw",
143	    override: (params?.override as any) ?? (() => {}),
144	    io: params?.io ?? "output",
145	    counter: 0,
146	    seen: new Map(),
147	    cycles: params?.cycles ?? "ref",
148	    reused: params?.reused ?? "inline",
149	    external: params?.external ?? undefined,
150	  };
151	}
