153	/** Applies the `unrepresentable` setting at a site with no JSON Schema equivalent. Under `"throw"`
154	 * the error is deferred: it is recorded on the seen entry and thrown in `finalize`, but only if
155	 * `override` did not give the node a JSON Schema form of its own. */
156	export function handleUnrepresentable(schema: schemas.$ZodType, ctx: ToJSONSchemaContext, message: string): void {
157	  if (ctx.unrepresentable === "throw") {
158	    const seen = ctx.seen.get(schema);
159	    if (seen) seen.unrepresentable = message;
160	    else throw new Error(message);
161	  }
162	}
