164	export function process<T extends schemas.$ZodType>(
165	  schema: T,
166	  ctx: ToJSONSchemaContext,
167	  _params: ProcessParams = { path: [], schemaPath: [] }
168	): JSONSchema.BaseSchema {
169	  const def = schema._zod.def as schemas.$ZodTypes["_zod"]["def"];
170	
171	  // check for schema in seens
172	  const seen = ctx.seen.get(schema);
173	
174	  if (seen) {
175	    seen.count++;
176	
177	    // check if cycle
178	    const isCycle = _params.schemaPath.includes(schema);
179	    if (isCycle) {
180	      seen.cycle = _params.path;
181	    }
182	
183	    return seen.schema;
184	  }
185	
186	  // initialize
187	  const result: Seen = { schema: {}, count: 1, cycle: undefined, path: _params.path };
188	  ctx.seen.set(schema, result);
189	
190	  // custom method overrides default behavior
191	  const overrideSchema = schema._zod.toJSONSchema?.();
192	  if (overrideSchema) {
193	    result.schema = overrideSchema as any;
194	  } else {
195	    const params = {
196	      ..._params,
197	      schemaPath: [..._params.schemaPath, schema],
198	      path: _params.path,
199	    };
200	
201	    if (schema._zod.processJSONSchema) {
202	      schema._zod.processJSONSchema(ctx, result.schema, params);
203	    } else {
204	      const _json = result.schema;
205	      const processor = ctx.processors[def.type];
206	      if (!processor) {
207	        throw new Error(`[toJSONSchema]: Non-representable type encountered: ${def.type}`);
208	      }
209	      processor(schema, ctx, _json, params);
210	    }
211	
212	    const parent = schema._zod.parent as T;
213	
214	    if (parent) {
215	      // Also set ref if processor didn't (for inheritance)
216	      if (!result.ref) result.ref = parent;
217	      process(parent, ctx, params);
218	      ctx.seen.get(parent)!.isParent = true;
219	    }
220	  }
221	
222	  // metadata
223	  const meta = ctx.metadataRegistry.get(schema);
224	  if (meta) assignProps(result.schema, meta);
225	
226	  if (ctx.io === "input" && isTransforming(schema)) {
227	    // examples/defaults only apply to output type of pipe
228	    delete result.schema.examples;
229	    delete result.schema.default;
230	  }
231	
232	  // set prefault as default
233	  if (ctx.io === "input" && "_prefault" in result.schema) result.schema.default ??= result.schema._prefault;
234	  delete result.schema._prefault;
235	
236	  // pulling fresh from ctx.seen in case it was overwritten
237	  const _result = ctx.seen.get(schema)!;
238	
239	  return _result.schema;
240	}
