242	export function extractDefs<T extends schemas.$ZodType>(
243	  ctx: ToJSONSchemaContext,
244	  schema: T
245	  // params: EmitParams
246	): void {
247	  // iterate over seen map;
248	  const root = ctx.seen.get(schema);
249	
250	  if (!root) throw new Error("Unprocessed schema. This is a bug in Zod.");
251	
252	  // Track ids to detect duplicates across different schemas
253	  const idToSchema = new Map<string, schemas.$ZodType>();
254	  for (const entry of ctx.seen.entries()) {
255	    const id = ctx.metadataRegistry.get(entry[0])?.id;
256	    if (id) {
257	      const existing = idToSchema.get(id);
258	      if (existing && existing !== entry[0]) {
259	        throw new Error(
260	          `Duplicate schema id "${id}" detected during JSON Schema conversion. Two different schemas cannot share the same id when converted together.`
261	        );
262	      }
263	      idToSchema.set(id, entry[0]);
264	    }
265	  }
266	
267	  // returns a ref to the schema
268	  // defId will be empty if the ref points to an external schema (or #)
269	  const makeURI = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): { ref: string; defId?: string } => {
270	    // comparing the seen objects because sometimes
271	    // multiple schemas map to the same seen object.
272	    // e.g. lazy
273	
274	    // external is configured
275	    const defsSegment = ctx.target === "draft-2020-12" ? "$defs" : "definitions";
276	    if (ctx.external) {
277	      const externalId = ctx.external.registry.get(entry[0])?.id; // ?? "__shared";// `__schema${ctx.counter++}`;
278	
279	      // check if schema is in the external registry
280	      const uriGenerator = ctx.external.uri ?? ((id: string) => id);
281	      if (externalId) {
282	        return { ref: uriGenerator(externalId) };
283	      }
284	
285	      // otherwise, add to __shared
286	      const id: string = entry[1].defId ?? (entry[1].schema.id as string) ?? `schema${ctx.counter++}`;
287	      entry[1].defId = id; // set defId so it will be reused if needed
288	      return { defId: id, ref: `${uriGenerator("__shared")}#/${defsSegment}/${id}` };
289	    }
290	
291	    if (entry[1] === root) {
292	      return { ref: "#" };
293	    }
294	
295	    // self-contained schema
296	    const uriPrefix = `#`;
297	    const defUriPrefix = `${uriPrefix}/${defsSegment}/`;
298	    const defId = entry[1].schema.id ?? `__schema${ctx.counter++}`;
299	    return { defId, ref: defUriPrefix + defId };
300	  };
301	
302	  // stored cached version in `def` property
303	  // remove all properties, set $ref
304	  const extractToDef = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): void => {
305	    // if the schema is already a reference, do not extract it
306	    if (entry[1].schema.$ref) {
307	      return;
308	    }
309	    const seen = entry[1];
310	    const { ref, defId } = makeURI(entry);
311	
312	    seen.def = { ...seen.schema };
313	    // defId won't be set if the schema is a reference to an external schema
314	    // or if the schema is the root schema
315	    if (defId) seen.defId = defId;
316	    // wipe away all properties except $ref
317	    const schema = seen.schema;
318	    for (const key in schema) {
319	      delete schema[key];
320	    }
321	    schema.$ref = ref;
322	  };
323	
324	  // throw on cycles
325	
326	  // break cycles
327	  if (ctx.cycles === "throw") {
328	    for (const entry of ctx.seen.entries()) {
329	      const seen = entry[1];
330	      if (seen.cycle) {
331	        throw new Error(
332	          "Cycle detected: " +
333	            `#/${seen.cycle?.join("/")}/<root>` +
334	            '\n\nSet the `cycles` parameter to `"ref"` to resolve cyclical schemas with defs.'
335	        );
336	      }
337	    }
338	  }
339	
340	  // extract schemas into $defs
341	  for (const entry of ctx.seen.entries()) {
342	    const seen = entry[1];
343	
344	    // convert root schema to # $ref
345	    if (schema === entry[0]) {
346	      extractToDef(entry); // this has special handling for the root schema
347	      continue;
348	    }
349	
350	    // extract schemas that are in the external registry
351	    if (ctx.external) {
352	      const ext = ctx.external.registry.get(entry[0])?.id;
353	      if (schema !== entry[0] && ext) {
354	        extractToDef(entry);
355	        continue;
356	      }
357	    }
358	
359	    // extract schemas with `id` meta
360	    const id = ctx.metadataRegistry.get(entry[0])?.id;
361	    if (id) {
362	      extractToDef(entry);
363	      continue;
364	    }
365	
366	    // break cycles
367	    if (seen.cycle) {
368	      // any
369	      extractToDef(entry);
370	      continue;
371	    }
372	
373	    // extract reused schemas
374	    if (seen.count > 1) {
375	      if (ctx.reused === "ref") {
376	        extractToDef(entry);
377	        // biome-ignore lint:
378	        continue;
379	      }
380	    }
381	  }
382	}
