398	function structuralSnapshot(schema: JSONSchema.BaseSchema): string {
399	  const structural: Record<string, unknown> = {};
400	  for (const key in schema) {
401	    if (!ANNOTATION_KEYS.has(key)) structural[key] = schema[key];
402	  }
403	  return JSON.stringify(structural);
404	}
