428	
429	      const refSeen = ctx.seen.get(ref)!;
430	      const refSchema = refSeen.schema;
431	
432	      // merge referenced schema into current
433	      if (refSchema.$ref && (ctx.target === "draft-07" || ctx.target === "draft-04" || ctx.target === "openapi-3.0")) {
434	        // older drafts can't combine $ref with other properties
435	        schema.allOf = schema.allOf ?? [];
436	        schema.allOf.push(refSchema);
437	      } else {
438	        assignProps(schema, refSchema);
439	      }
440	      // restore child's own properties (child wins)
441	      assignProps(schema, _cached);
442	
443	      const isParentRef = zodSchema._zod.parent === ref;
444	
445	      // For parent chain, child is a refinement - remove parent-only properties
446	      if (isParentRef) {
447	        for (const key in schema) {
448	          if (key === "$ref" || key === "allOf") continue;
449	          if (!(key in _cached)) {
450	            delete schema[key];
451	          }
452	        }
453	      }
454	
455	      // When ref was extracted to $defs, remove properties that match the definition
456	      if (refSchema.$ref && refSeen.def) {
457	        for (const key in schema) {
458	          if (key === "$ref" || key === "allOf") continue;
459	          if (key in refSeen.def && JSON.stringify(schema[key]) === JSON.stringify(refSeen.def[key])) {
460	            delete schema[key];
461	          }
462	        }
463	      }
464	    }
465	
466	    // If parent was extracted (has $ref), propagate $ref to this schema
467	    // This handles cases like: readonly().meta({id}).describe()
