469	    const parent = zodSchema._zod.parent;
470	    if (parent && parent !== ref) {
471	      // Ensure parent is processed first so its def has inherited properties
472	      flattenRef(parent);
473	      const parentSeen = ctx.seen.get(parent);
474	      if (parentSeen?.schema.$ref) {
475	        schema.$ref = parentSeen.schema.$ref;
476	        // De-duplicate with parent's definition
